insert into public.exercises (name, muscle_group, description, category, movement_pattern, image_url) values
('Überzüge mit Kurzhantel', 'Latissimus, Brust, Trizeps', 'Ausführung: Quer auf einer Bank liegend (nur Schultern aufliegend), Füße fest auf dem Boden und Hüfte tief unter der Bank, eine Kurzhantel mit beiden Händen über der Brust halten und mit leicht gebeugten Armen hinter den Kopf absenken, bis eine deutliche Dehnung im Latissimus spürbar ist, dann kontrolliert zurückführen. Ausrüstung: Kurzhantel, Bank. Worauf achten: Hüfte durchgehend tief halten, Rippenbogen nicht überstrecken, Ellbogenwinkel während der gesamten Bewegung beibehalten, moderates Gewicht wählen, da die Schultern in der Dehnungsposition stark beansprucht werden.', 'Kraft', 'pull_oberkoerper', null),
('Überzüge am Kabelzug', 'Latissimus, Brust', 'Ausführung: Am hohen Kabelzug mit stabilem Stand und leicht vorgebeugtem Oberkörper die Arme fast gestreckt halten und die Stange oder das Seil in einer Bogenbewegung von oben bis vor die Oberschenkel ziehen, kontrolliert zurückführen. Ausrüstung: Kabelzug mit Stangen- oder Seilgriff. Worauf achten: Arme bleiben während der gesamten Bewegung nahezu gestreckt, Bewegung kommt aus dem Latissimus statt aus den Armen, Oberkörper stabil, Rumpf leicht angespannt.', 'Kraft', 'pull_oberkoerper', null),
('V-Lift mit Band', 'Schulter, Trapez', 'Ausführung: Im Stand oder in Bauchlage das Band mit beiden Händen straffen und in V-Form diagonal über Kopf nach oben-außen ziehen, Schulterblätter dabei zusammenziehen, kontrolliert bis zur Ausgangsposition zurückführen. Ausrüstung: Widerstandsband. Worauf achten: Bewegung kommt aus dem oberen Rücken statt aus den Armen, kein Hohlkreuz, Ellbogen bleiben lang gestreckt, leichten Bandwiderstand wählen, um die Technik sauber zu halten.', 'Kraft', 'pull_oberkoerper', null),
('V-Lift mit Kurzhantel', 'Schulter, Trapez', 'Ausführung: In Bauchlage auf einer Schrägbank mit Stirn auf der Polsterung die Arme mit leichten Kurzhanteln diagonal nach vorn-oben in Y-Form anheben, Schulterblätter zusammenziehen, kontrolliert absenken. Ausrüstung: leichte Kurzhanteln, Schrägbank. Worauf achten: Sehr geringes Gewicht wählen, Bewegung langsam und kontrolliert, kein Schwung, Kopf und Nacken entspannt lassen.', 'Kraft', 'pull_oberkoerper', null),
('Außenrotationen für die Schulter', 'Schulter', 'Ausführung: Ellbogen im 90°-Winkel am Körper fixiert (Handtuch/Kissen unter der Achsel), den Unterarm mit leichter Kurzhantel oder Band langsam nach außen rotieren, bis eine angenehme Spannung in der Schulter spürbar ist, kontrolliert zurückführen. Ausrüstung: leichte Kurzhantel oder Widerstandsband. Worauf achten: Ellbogen bleibt während der gesamten Bewegung am Körper fixiert, sehr geringes Gewicht, Fokus auf die Rotatorenmanschette statt auf Tempo, Bewegung nicht ruckartig ausführen.', 'Kraft', 'pull_oberkoerper', null),
('Innenrotationen für die Schulter', 'Schulter', 'Ausführung: Ellbogen im 90°-Winkel am Körper fixiert, den Unterarm mit leichter Kurzhantel oder Band langsam vor dem Bauch nach innen rotieren, kontrolliert zurückführen. Ausrüstung: leichte Kurzhantel oder Widerstandsband. Worauf achten: Ellbogen bleibt während der gesamten Bewegung fixiert, kontrolliertes Tempo, kein Schwung aus der Schulter, sehr geringes Gewicht wählen.', 'Kraft', 'push_oberkoerper', null),
('Negativ-Bankdrücken (Langhantel)', 'Brust, Trizeps', 'Ausführung: Auf der Negativbank (Kopf tiefer als Becken) liegend mit fixierten Beinen die Langhantel kontrolliert vom unteren Brustbereich nach oben drücken, bis die Arme fast gestreckt sind, kontrolliert wieder absenken. Ausrüstung: Langhantel, Negativbank. Worauf achten: Sicherung/Spotter verwenden, Schulterblätter fixiert, Stange kontrolliert und ohne Aufprall im unteren Brustbereich aufsetzen, moderates Gewicht wegen der ungewohnten Kopftieflage wählen.', 'Kraft', 'push_oberkoerper', null),
('Kurzhantel-Schulterdrücken (sitzend)', 'Schulter, Trizeps', 'Ausführung: Sitzend mit Rückenlehne und Füßen fest auf dem Boden die Kurzhanteln von Schulterhöhe nach oben drücken, bis die Arme fast gestreckt sind, kontrolliert bis auf Schulterhöhe absenken. Ausrüstung: Kurzhanteln, Bank mit Rückenlehne. Worauf achten: Rücken durchgehend an der Lehne, kein Hohlkreuz, Handgelenke gerade über den Ellbogen, Ellbogen nicht komplett durchdrücken.', 'Kraft', 'push_oberkoerper', null),
('Langhantelrudern im Untergriff', 'Latissimus, Bizeps, Trapez', 'Ausführung: Vorgebeugt mit leicht gebeugten Knien und Untergriff (Handflächen nach oben) die Langhantel zum Bauch heranziehen, Ellbogen eng am Körper, kontrolliert bis zur fast vollen Armstreckung absenken. Ausrüstung: Langhantel. Worauf achten: Rücken gerade und Oberkörperwinkel während der gesamten Bewegung stabil halten, kein Schwung aus dem unteren Rücken, Rumpf angespannt.', 'Kraft', 'pull_oberkoerper', null),
('T-Bar-Rudern', 'Latissimus, Trapez, Bizeps', 'Ausführung: Über der T-Bar-Stange stehend, Oberkörper vorgebeugt und Rücken gerade, den Griff zum Bauch heranziehen, Schulterblätter zusammenziehen, kontrolliert bis zur fast vollen Armstreckung absenken. Ausrüstung: T-Bar-Rudergerät oder Langhantel in der Ecke mit V-Griff. Worauf achten: Rücken während der gesamten Bewegung gerade, Knie leicht gebeugt, Zug aus dem Rücken statt aus den Armen, kein Schwung aus dem unteren Rücken.', 'Kraft', 'pull_oberkoerper', null),
('Rumänisches Kreuzheben (Langhantel)', 'Oberschenkel, Gesäß, Rückenstrecker', 'Ausführung: Mit fast gestreckten Beinen und angespanntem Rumpf die Langhantel eng am Körper entlang absenken, bis eine deutliche Dehnung in der Oberschenkelrückseite spürbar ist, dann über die Hüftstreckung wieder aufrichten. Ausrüstung: Langhantel. Worauf achten: Rücken durchgehend gerade, Bewegung kommt aus der Hüfte statt aus dem unteren Rücken, Stange bleibt körpernah, nur so tief absenken, wie der Rücken gerade bleibt.', 'Kraft', 'hintere_beinkette', null),
('Frontkniebeuge (Langhantel)', 'Oberschenkel, Gesäß', 'Ausführung: Die Langhantel vorn auf den Schultern ablegen (Clean-Griff oder verschränkte Arme), Rumpf anspannen, in die Kniebeuge absenken und über die Fersen kraftvoll wieder aufstehen. Ausrüstung: Langhantel, ggf. Squat-Rack. Worauf achten: Oberkörper möglichst aufrecht halten, Ellbogen hoch, Knie in Fußrichtung, aus dem Squat-Rack in Griffhöhe absetzen, um sicher ein- und auszusteigen.', 'Kraft', 'vordere_beinkette', null),
('Hackenschmidt-Maschine (Hack Squat)', 'Oberschenkel, Gesäß', 'Ausführung: Mit dem Rücken flächig an der geneigten Rückenplatte der Maschine und hüftbreit platzierten Füßen in die Kniebeuge absenken, dann durch Strecken der Beine kontrolliert wieder aufstehen. Ausrüstung: Hackenschmidt-Maschine. Worauf achten: Rücken bleibt durchgehend an der Platte, Knie in Fußrichtung, kontrolliertes Tempo ohne Durchstoßen der Knie am oberen Punkt, Sicherungsarretierung erst nach vollständigem Stand lösen.', 'Kraft', 'vordere_beinkette', null),
('Rückwärtiger Ausfallschritt mit der Langhantel', 'Oberschenkel, Gesäß', 'Ausführung: Mit der Langhantel im Nacken und stabilem Stand einen großen Schritt rückwärts setzen, das hintere Knie kontrolliert Richtung Boden absenken, dann über die vordere Ferse zurück in den Stand drücken. Ausrüstung: Langhantel. Worauf achten: Oberkörper aufrecht, vorderes Knie bleibt über dem Fuß und fällt nicht nach innen, kontrolliertes Tempo, Rumpf während des gesamten Schritts stabil.', 'Kraft', 'vordere_beinkette', null),
('Konzentrationscurls mit Kurzhantel', 'Bizeps', 'Ausführung: Sitzend mit breitem Stand den Ellbogen an der Innenseite des Oberschenkels abstützen und die Kurzhantel durch Beugen des Arms nach oben führen, kontrolliert bis zur fast vollen Streckung absenken. Ausrüstung: Kurzhantel, Bank. Worauf achten: Oberarm bleibt während der gesamten Bewegung fixiert, Bewegung isoliert im Ellbogengelenk, kein Schwung aus der Schulter.', 'Kraft', 'pull_oberkoerper', null),
('Enges Bankdrücken (Close-Grip)', 'Trizeps, Brust', 'Ausführung: Auf der Flachbank liegend mit festem Fußkontakt zum Boden die Langhantel mit schulterbreitem oder engerem Griff von der Brust nach oben drücken, Ellbogen eng am Körper führen, kontrolliert bis zur Brust absenken. Ausrüstung: Langhantel, Bank. Worauf achten: Ellbogen zeigen nach hinten statt nach außen, Handgelenke gerade, Sicherung/Spotter bei hohem Gewicht verwenden, Stange kontrolliert ohne Aufprall auf der Brust aufsetzen.', 'Kraft', 'push_oberkoerper', null),
('Dips an der Assistenzmaschine', 'Brust, Trizeps', 'Ausführung: Auf der Kniestütze der Assistenzmaschine mit gestreckten Armen starten und den Oberkörper zwischen den Griffen kontrolliert absenken, bis die Ellbogen etwa 90° gebeugt sind, dann wieder nach oben drücken. Ausrüstung: Dip-/Klimmzug-Assistenzmaschine. Worauf achten: Gewichtsunterstützung so wählen, dass die Bewegung sauber gelingt, leichte Vorlage für mehr Brust- oder aufrechte Haltung für mehr Trizepsbeteiligung, Schultern nicht zu tief absinken lassen.', 'Kraft', 'push_oberkoerper', null),
('Shrugs mit der Langhantel', 'Trapez', 'Ausführung: Im aufrechten Stand die Langhantel mit gestreckten Armen vor dem Körper halten und die Schultern gerade nach oben Richtung Ohren ziehen, kurz halten, kontrolliert absenken. Ausrüstung: Langhantel. Worauf achten: Keine Rollbewegung in den Schultern, Bewegung rein vertikal, Nacken entspannt lassen, kein Schwung aus den Knien.', 'Kraft', 'pull_oberkoerper', null),
('Shrugs mit Kurzhanteln', 'Trapez', 'Ausführung: Im aufrechten Stand mit einer Kurzhantel in jeder herabhängenden Hand die Schultern gerade nach oben ziehen, kurz halten, kontrolliert absenken. Ausrüstung: Kurzhanteln. Worauf achten: Keine Rollbewegung, Bewegung rein vertikal, aufrechter Stand, Nacken entspannt lassen.', 'Kraft', 'pull_oberkoerper', null),
('Beinadduktion am Kabelzug', 'Oberschenkel', 'Ausführung: Seitlich zum unteren Kabelzug stehend mit Fußmanschette das äußere Bein gestreckt vor dem Standbein nach innen führen, kontrolliert zurückführen. Ausrüstung: Kabelzug mit Fußmanschette. Worauf achten: Oberkörper stabil, Bewegung kontrolliert ohne Schwung, Halt am Gerät zur Balance, Standbein leicht gebeugt.', 'Kraft', 'sonstige', null),
('Beinabduktion am Kabelzug', 'Gesäß', 'Ausführung: Seitlich zum unteren Kabelzug stehend mit Fußmanschette das innere Bein gestreckt seitlich vom Körper wegführen, kontrolliert zurückführen. Ausrüstung: Kabelzug mit Fußmanschette. Worauf achten: Oberkörper aufrecht, Bewegung aus der Hüfte statt aus dem Rumpf, kein Ausweichen ins Hohlkreuz, Standbein leicht gebeugt.', 'Kraft', 'sonstige', null),
('Scott-Curls (SZ-Stange)', 'Bizeps', 'Ausführung: Die Oberarme flächig auf der Schrägpolsterung des Scott-Pults ablegen und die SZ-Stange durch Beugen der Ellbogen nach oben führen, kontrolliert bis kurz vor die volle Streckung absenken. Ausrüstung: SZ-Stange, Scott-Pult (Preacher-Bank). Worauf achten: Oberarme bleiben während der gesamten Bewegung auf dem Polster, untere Endposition nicht mit Schwung durchdrücken, um den Ellbogen zu schonen.', 'Kraft', 'pull_oberkoerper', null),
('Trizeps-Kickback mit Kurzhantel', 'Trizeps', 'Ausführung: Vorgebeugt mit einer Hand und dem gleichseitigen Knie auf der Bank abgestützt, den Rücken gerade und den Oberarm parallel zum Rücken halten, den Unterarm mit der Kurzhantel nach hinten strecken, kontrolliert zurückführen. Ausrüstung: Kurzhantel, Bank. Worauf achten: Oberarm bleibt während der gesamten Bewegung ruhig und parallel zum Rücken, Bewegung ausschließlich im Ellbogengelenk, kein Schwung.', 'Kraft', 'push_oberkoerper', null),
('Kabelzug-Frontheben', 'Schulter', 'Ausführung: Am unteren Kabelzug mit stabilem Stand und einer Hand den Griff vor dem Körper bis auf Schulterhöhe anheben, kontrolliert absenken. Ausrüstung: Kabelzug mit Einzelgriff. Worauf achten: Leichte Beugung im Ellbogen beibehalten, kein Schwung aus dem Rumpf, konstante Spannung im Kabel, nicht über Schulterhöhe anheben.', 'Kraft', 'push_oberkoerper', null),
('Kabelzug-Seitheben', 'Schulter', 'Ausführung: Seitlich zum unteren Kabelzug stehend mit der außenliegenden Hand und leicht gebeugtem Ellbogen den Griff seitlich bis auf Schulterhöhe anheben, kontrolliert absenken. Ausrüstung: Kabelzug mit Einzelgriff. Worauf achten: Oberkörper stabil, kein Schwung aus der Hüfte, konstante Spannung im Kabel während der gesamten Bewegung, Schulter unten lassen statt hochzuziehen.', 'Kraft', 'push_oberkoerper', null),
('Gesäßmaschine (Hüftstrecker-Maschine)', 'Gesäß', 'Ausführung: An der Maschine mit stabil abgestütztem Oberkörper und angewinkeltem Bein das Polster durch Strecken der Hüfte nach hinten drücken, kontrolliert zurückführen. Ausrüstung: Hüftstrecker-/Gesäßmaschine. Worauf achten: Oberkörper stabil an der Auflage, Bewegung aus der Hüfte statt aus dem unteren Rücken, Gesäß am Endpunkt aktiv anspannen, kein Hohlkreuz.', 'Kraft', 'hintere_beinkette', null),
('Beinpresse einbeinig', 'Oberschenkel, Gesäß', 'Ausführung: An der Beinpresse mit nur einem mittig auf der Plattform platzierten Bein die Plattform nach oben drücken, kontrolliert bis zum rechten Winkel im Knie absenken, dann die Seite wechseln. Ausrüstung: Beinpresse. Worauf achten: Knie in Fußrichtung, unterer Rücken bleibt durchgehend an der Lehne, deutlich geringeres Gewicht als beidbeinig wählen, Gesäß nicht von der Sitzfläche abheben.', 'Kraft', 'vordere_beinkette', null),
('Wadenheben an der Beinpresse', 'Waden', 'Ausführung: An der Beinpresse mit nahezu gestreckten Beinen nur über die Fußballen auf die Plattform drücken, Fersen maximal anheben, kontrolliert bis zur deutlichen Dehnung absenken. Ausrüstung: Beinpresse. Worauf achten: Beine bleiben nahezu gestreckt ohne die Knie durchzudrücken, volle Bewegungsamplitude nutzen, kein Wippen, Sicherungsarretierung beachten.', 'Kraft', 'hintere_beinkette', null),
('Good Mornings (Langhantel)', 'Oberschenkel, Rückenstrecker, Gesäß', 'Ausführung: Mit der Langhantel im Nacken und leicht gebeugten Knien den Oberkörper aus der Hüfte nach vorn beugen, bis eine deutliche Dehnung in der Oberschenkelrückseite spürbar ist, dann über die Hüftstreckung wieder aufrichten. Ausrüstung: Langhantel. Worauf achten: Rücken während der gesamten Bewegung gerade, Knie nur leicht gebeugt, geringes Gewicht wählen und nicht tiefer beugen, als der Rücken gerade bleibt.', 'Kraft', 'hintere_beinkette', null),
('Diagonale Crunches', 'Bauchmuskeln', 'Ausführung: In Rückenlage mit angewinkelten Beinen und Händen locker an den Schläfen abwechselnd den Ellbogen zum gegenüberliegenden Knie führen, während das andere Bein gestreckt bleibt. Ausrüstung: Matte. Worauf achten: Bewegung aus der Bauchmuskulatur einleiten, unteren Rücken am Boden lassen, kontrolliertes Tempo ohne Zug am Nacken mit den Händen.', 'Bodyweight', 'rumpf_vorne', null),
('Diamant-Liegestütz', 'Brust, Trizeps', 'Ausführung: Liegestütz mit Händen dicht zusammen unter der Brust (Daumen und Zeigefinger bilden eine Raute), Körper kontrolliert absenken, bis die Brust sich der Raute nähert, und wieder nach oben drücken. Ausrüstung: Matte. Worauf achten: Rumpf und Gesäß angespannt, Ellbogen nah am Körper statt nach außen, bei Bedarf auf den Knien ausführen, um das Handgelenk zu entlasten.', 'Bodyweight', 'push_oberkoerper', null),
('Archer-Liegestütz', 'Brust, Trizeps, Schulter', 'Ausführung: Aus breiter Liegestützposition mit angespanntem Rumpf den Körper kontrolliert zu einer Seite absenken, während der andere Arm gestreckt zur Seite ausgestreckt bleibt, dann zurück in die Mitte drücken und Seite wechseln. Ausrüstung: Matte. Worauf achten: Rumpf stabil und Becken gerade, kontrolliertes Tempo, bei Bedarf mit den Knien am Boden ausführen.', 'Bodyweight', 'push_oberkoerper', null),
('Klappmesser (V-Ups)', 'Bauchmuskeln', 'Ausführung: In Rückenlage mit gestreckten Armen und Beinen gleichzeitig Oberkörper und Beine kontrolliert anheben, Hände Richtung Füße führen, dann kontrolliert zurück in die Ausgangsposition. Ausrüstung: Matte. Worauf achten: Bewegung aus der Bauchmuskulatur einleiten, unteren Rücken nicht überlasten, bei Beschwerden im unteren Rücken die Beine angewinkelt ausführen.', 'Bodyweight', 'rumpf_vorne', null),
('Russian Twists (ohne Gewicht)', 'Bauchmuskeln', 'Ausführung: Im Sitzen mit leicht angehobenen, angewinkelten Beinen den Oberkörper leicht zurücklehnen und abwechselnd mit den Händen den Boden neben der Hüfte berühren. Ausrüstung: Matte. Worauf achten: Rücken möglichst gerade halten statt rund zu werden, Bewegung aus der Rumpfrotation, kontrolliertes Tempo, bei Bedarf die Füße am Boden lassen, um den unteren Rücken zu entlasten.', 'Bodyweight', 'rumpf_vorne', null),
('Beckenlift einbeinig', 'Gesäß, Oberschenkel', 'Ausführung: In Rückenlage mit einem aufgestellten Bein das andere Bein strecken und die Hüfte kontrolliert anheben, bis Schultern-Hüfte-Knie eine Linie bilden, kontrolliert absenken. Ausrüstung: Matte. Worauf achten: Becken bleibt gerade und waagerecht, kein Ausweichen zur Seite, Gesäß am oberen Punkt aktiv anspannen, kein Hohlkreuz.', 'Bodyweight', 'hintere_beinkette', null),
('Wandsitz (Wall Sit)', 'Oberschenkel', 'Ausführung: Mit dem Rücken flächig an der Wand in die Kniebeuge-Position gehen, bis die Oberschenkel etwa parallel zum Boden sind, Position ruhig statisch halten. Ausrüstung: Wand. Worauf achten: Knie über den Fußgelenken und in Fußrichtung, Rücken durchgehend flächig an der Wand, gleichmäßige Atmung während des Haltens statt die Luft anzuhalten.', 'Bodyweight', 'vordere_beinkette', null),
('Ausfallschritte im Gehen (ohne Gewicht)', 'Oberschenkel, Gesäß', 'Ausführung: Im Gehen abwechselnd große, kontrollierte Schritte nach vorn setzen, das hintere Knie Richtung Boden absenken, über die vordere Ferse aufstehen und in den nächsten Schritt übergehen. Ausrüstung: keine. Worauf achten: Oberkörper aufrecht, vorderes Knie bleibt über dem Fuß und fällt nicht nach innen, kontrolliertes Tempo, Rumpf stabil halten.', 'Bodyweight', 'vordere_beinkette', null),
('Kniebeuge (Bodyweight)', 'Oberschenkel, Gesäß', 'Ausführung: Im hüftbreiten Stand mit leicht nach außen gedrehten Füßen das Gesäß nach hinten-unten absenken, bis die Oberschenkel etwa parallel zum Boden sind, dann über die Fersen wieder aufstehen. Ausrüstung: keine. Worauf achten: Knie in Fußrichtung und fallen nicht nach innen, Rücken gerade, Gewicht auf der gesamten Fußsohle statt auf den Zehenspitzen.', 'Bodyweight', 'vordere_beinkette', null),
('Reverse Plank (Unterarmstütz rückwärts)', 'Bauchmuskeln, Rückenstrecker', 'Ausführung: Im Sitzen mit hinter dem Körper aufgestützten Händen oder Unterarmen die Hüfte kontrolliert anheben, bis der Körper eine gerade Linie bildet, Position ruhig halten. Ausrüstung: Matte. Worauf achten: Gesäß aktiv anspannen, Schultern über den Stützpunkten, gleichmäßige Atmung, Kopf in Verlängerung der Wirbelsäule lassen.', 'Bodyweight', 'rumpf_hinten', null),
('Seitstütz mit Hüftheben (Side Plank Hip Dips)', 'Bauchmuskeln', 'Ausführung: Im Unterarm-Seitstütz mit Ellbogen unter der Schulter die Hüfte kontrolliert Richtung Boden absenken und wieder anheben, ohne den Boden zu berühren. Ausrüstung: Matte. Worauf achten: Körper bleibt in einer Linie, kein Vor- oder Zurückkippen, Bewegung kommt aus der seitlichen Rumpfmuskulatur, kontrolliertes Tempo.', 'Bodyweight', 'rumpf_vorne', null),
('Beckenlift mit Beinheben (Glute Bridge March)', 'Gesäß, Bauchmuskeln', 'Ausführung: In der Beckenlift-Position mit angespanntem Gesäß die Hüfte oben halten und abwechselnd ein Knie kontrolliert zur Brust heranziehen, ohne die Hüfte absinken zu lassen. Ausrüstung: Matte. Worauf achten: Becken bleibt während des gesamten Übungsablaufs stabil und gerade, Gesäß durchgehend angespannt, kein Ausweichen zur Seite.', 'Bodyweight', 'hintere_beinkette', null),
('Spiderman-Liegestütz', 'Brust, Trizeps, Bauchmuskeln', 'Ausführung: Während der Abwärtsbewegung eines Liegestützes ein Knie seitlich Richtung gleichseitigen Ellbogen ziehen, dann wieder strecken und nach oben drücken, Seite wechseln. Ausrüstung: Matte. Worauf achten: Rumpf stabil und Becken gerade, Bewegung kontrolliert ohne Schwung, bei Bedarf auf den Knien ausführen.', 'Bodyweight', 'push_oberkoerper', null),
('Pike Push-Up (Schulterliegestütz)', 'Schulter, Trizeps', 'Ausführung: Aus dem umgekehrten V (Hüfte hoch, Hände und Füße am Boden) den Oberkörper kontrolliert absenken, bis sich der Kopf dem Boden annähert, dann wieder kraftvoll nach oben drücken. Ausrüstung: Matte. Worauf achten: Hüfte bleibt während der gesamten Bewegung hoch, Bewegung wie ein vertikaler Liegestütz, Blick leicht nach hinten zwischen die Hände, Kopf kontrolliert statt mit Schwung absenken.', 'Bodyweight', 'push_oberkoerper', null),
('Klimmzug im Untergriff (Chin-Up)', 'Latissimus, Bizeps', 'Ausführung: Mit schulterbreitem Untergriff (Handflächen zum Gesicht) an der Stange hängend den Körper durch Zug der Rückenmuskulatur nach oben ziehen, bis das Kinn über der Stange ist, kontrolliert bis zur fast vollen Armstreckung absenken. Ausrüstung: Klimmzugstange. Worauf achten: Schultern aktiv nach unten ziehen, kein Schwung, volle Bewegungsamplitude nutzen, Rumpf stabil halten.', 'Bodyweight', 'pull_oberkoerper', null),
('Australische Klimmzüge (Inverted Row)', 'Latissimus, Bizeps, Trapez', 'Ausführung: Unter einer tief hängenden Stange oder an Ringen mit gestrecktem, angespanntem Körper den Oberkörper zur Stange hochziehen, Schulterblätter zusammenziehen, kontrolliert bis zur fast vollen Armstreckung absenken. Ausrüstung: Klimmzugstange (tief) oder Ringe/Schlaufen. Worauf achten: Körper bleibt durchgehend in einer geraden Linie, Ferse aufgesetzt, Schwierigkeitsgrad über den Körperwinkel steuern, Gesäß nicht durchhängen lassen.', 'Bodyweight', 'pull_oberkoerper', null),
('Step-Down (exzentrisches Beintraining)', 'Oberschenkel, Gesäß', 'Ausführung: Auf einer Erhöhung stehend das freie Bein langsam kontrolliert nach vorn-unten absenken, bis die Ferse fast den Boden berührt, dann über das Standbein zurück nach oben drücken. Ausrüstung: Stufe oder stabile Erhöhung. Worauf achten: Bewegung sehr langsam und kontrolliert, Knie des Standbeins bleibt in Fußrichtung und fällt nicht nach innen, Standbein trägt die gesamte Kontrolle.', 'Bodyweight', 'vordere_beinkette', null),
('Curtsy Lunge (Reverenz-Ausfallschritt)', 'Oberschenkel, Gesäß', 'Ausführung: Mit einem Bein diagonal hinter das Standbein kreuzen und das hintere Knie kontrolliert Richtung Boden absenken, dann über das vordere Bein zurück in den Stand drücken. Ausrüstung: keine. Worauf achten: Oberkörper aufrecht, Knie des vorderen Beins bleibt stabil über dem Fuß, kontrolliertes Tempo, auf sicheren Halt beim Kreuzschritt achten.', 'Bodyweight', 'vordere_beinkette', null),
('Beinheben liegend (Lying Leg Raise)', 'Bauchmuskeln', 'Ausführung: In Rückenlage mit den Händen locker neben dem Körper die gestreckten Beine gemeinsam anheben, bis sie senkrecht stehen, kontrolliert wieder absenken, ohne den unteren Rücken vom Boden abzuheben. Ausrüstung: Matte. Worauf achten: Unterer Rücken bleibt durchgehend am Boden, Bewegung kontrolliert ohne Schwung, bei Beschwerden im unteren Rücken die Beine leicht angewinkelt ausführen.', 'Bodyweight', 'rumpf_vorne', null),
('Seitliches Beinheben im Liegen', 'Gesäß, Oberschenkel', 'Ausführung: In Seitlage mit gestrecktem Körper und leicht abgestütztem Kopf das obere Bein kontrolliert anheben und wieder absenken, ohne dass das Becken nach hinten kippt. Ausrüstung: Matte. Worauf achten: Rumpf stabil, Bewegung isoliert aus der Hüfte, kontrolliertes Tempo ohne Schwung, Fußspitze zeigt nach vorn statt nach oben.', 'Bodyweight', 'sonstige', null),
('Unterarmstütz mit Schulterklopfen (Plank Shoulder Taps)', 'Bauchmuskeln, Schulter', 'Ausführung: Im hohen Stütz (Liegestützposition) mit angespanntem Rumpf abwechselnd mit einer Hand die gegenüberliegende Schulter berühren, ohne das Becken zu verdrehen. Ausrüstung: Matte. Worauf achten: Becken bleibt ruhig und gerade, Füße etwas breiter stellen für mehr Stabilität, kontrolliertes Tempo statt schnellem Tempo mit Ausweichbewegung.', 'Bodyweight', 'rumpf_vorne', null),
('Schulterkreisen', 'Schultern', 'Ausführung: Im aufrechten Stand die Schultern großzügig und langsam nach vorn und anschließend nach hinten kreisen lassen. Ausrüstung: keine. Worauf achten: Bewegung groß und langsam ausführen, Arme locker hängen lassen, Atmung ruhig und gleichmäßig.', 'Mobilisation', 'sonstige', null),
('Nackendehnung im Sitzen', 'Nacken, Halswirbelsäule', 'Ausführung: Im Sitzen mit aufrechtem Oberkörper den Kopf sanft zur Seite neigen, bis eine leichte Dehnung im seitlichen Nacken spürbar ist, Position ca. 20-30 Sekunden ruhig halten, Seite wechseln. Ausrüstung: keine, ggf. Stuhl. Worauf achten: Bewegung sehr sanft und ohne Ziehen mit der Hand am Kopf, gleichmäßige Atmung, Schulter der gedehnten Seite bewusst unten lassen.', 'Mobilisation', 'sonstige', null),
('Brustdehnung im Türrahmen', 'Brust, Schultern', 'Ausführung: Unterarm im rechten Winkel an den Türrahmen anlegen und den Oberkörper leicht nach vorn drehen, bis eine deutliche, aber angenehme Dehnung in der Brust spürbar ist, Position ca. 20-30 Sekunden halten, Seite wechseln. Ausrüstung: Türrahmen. Worauf achten: Dehnung sanft aufbauen, keine ruckartigen Bewegungen, gleichmäßige Atmung, Schulter nicht hochziehen.', 'Mobilisation', 'push_oberkoerper', null),
('Latissimus-Dehnung an der Stange', 'Rücken, Latissimus', 'Ausführung: An einer Stange oder einem festen Halt mit gestreckten Armen hängen bzw. das Becken nach hinten absenken, bis eine deutliche Dehnung im seitlichen Rücken spürbar ist, Position ca. 20-30 Sekunden halten. Ausrüstung: Klimmzugstange oder fester Halt. Worauf achten: Schultern entspannt, Dehnung langsam aufbauen statt ruckartig, gleichmäßige Atmung, bei Handgelenkbeschwerden Griff anpassen.', 'Mobilisation', 'pull_oberkoerper', null),
('Hüftbeuger-Dehnung im Ausfallschritt', 'Hüftbeuger', 'Ausführung: Im tiefen Ausfallschritt mit aufgestelltem hinteren Knie das Becken kontrolliert nach vorn-unten schieben, bis eine deutliche Dehnung in der Hüftvorderseite des hinteren Beins spürbar ist, Position ca. 20-30 Sekunden halten, Seite wechseln. Ausrüstung: Matte. Worauf achten: Oberkörper aufrecht, Becken nicht zur Seite kippen, sanft und ohne Wippen in die Dehnung gehen.', 'Mobilisation', 'vordere_beinkette', null),
('Wadendehnung an der Wand', 'Waden', 'Ausführung: Mit gestrecktem hinteren Bein und durchgehend aufgesetzter Ferse gegen eine Wand lehnen, bis eine deutliche Dehnung in der Wade spürbar ist, Position ca. 20-30 Sekunden halten, Seite wechseln. Ausrüstung: Wand. Worauf achten: Ferse bleibt am Boden, Fuß zeigt gerade nach vorn, Dehnung langsam aufbauen statt federnd zu wippen.', 'Mobilisation', 'hintere_beinkette', null),
('Piriformis-Dehnung (Figure-4)', 'Gesäß, Hüfte', 'Ausführung: In Rückenlage einen Knöchel auf das gegenüberliegende Knie legen und das freie Bein mit beiden Händen zur Brust heranziehen, bis eine deutliche Dehnung im Gesäß spürbar ist, Position ca. 20-30 Sekunden halten, Seite wechseln. Ausrüstung: Matte. Worauf achten: Unterer Rücken bleibt am Boden, Dehnung sanft aufbauen statt zu ziehen, gleichmäßige Atmung.', 'Mobilisation', 'hintere_beinkette', null),
('Schmetterlingsdehnung', 'Adduktoren, Innenschenkel', 'Ausführung: Im Sitzen mit aufrechtem Oberkörper die Fußsohlen zusammenführen und die Knie sanft mit den Ellbogen Richtung Boden drücken, Position ca. 20-30 Sekunden halten. Ausrüstung: Matte. Worauf achten: Rücken gerade halten statt rund zu werden, Dehnung langsam und ohne Wippen aufbauen.', 'Mobilisation', 'sonstige', null),
('Rumpfrotation im Stehen', 'Rumpf, Wirbelsäule', 'Ausführung: Im hüftbreiten Stand mit leicht gebeugten Knien den Oberkörper locker und kontrolliert von einer Seite zur anderen rotieren lassen, Arme schwingen dabei entspannt mit. Ausrüstung: keine. Worauf achten: Hüfte bleibt stabil nach vorn ausgerichtet, Bewegung kommt aus der Brustwirbelsäule, keine ruckartigen Bewegungen.', 'Mobilisation', 'sonstige', null),
('Kindhaltung (Child''s Pose)', 'Rücken, Hüfte', 'Ausführung: Aus dem Fersensitz die Arme nach vorn ausstrecken und den Oberkörper entspannt Richtung Boden absenken, Position ca. 30-60 Sekunden halten. Ausrüstung: Matte. Worauf achten: Gesäß bleibt auf oder nah an den Fersen, Atmung tief und ruhig in den Rücken, bei Knie- oder Knöchelbeschwerden ein Kissen unterlegen.', 'Mobilisation', 'rumpf_hinten', null),
('Thread the Needle (dynamische BWS-Rotation)', 'Brustwirbelsäule, Schultern', 'Ausführung: Im Vierfüßlerstand einen Arm unter dem Körper hindurchführen, bis Schulter und Kopf den Boden berühren, dann kontrolliert zurückrotieren und den gleichen Arm zur Decke strecken, Blick folgt der Hand. Ausrüstung: Matte. Worauf achten: Hüfte bleibt ruhig und stabil, Bewegung kommt aus der Brustwirbelsäule, langsames Tempo ohne Schwung.', 'Mobilisation', 'sonstige', null),
('Hüftöffner im Kniestand', 'Hüfte', 'Ausführung: Im hohen Kniestand mit einem aufgestellten Bein und stabilem Oberkörper das Becken kontrolliert kreisen lassen bzw. seitlich verlagern, um die Hüfte zu öffnen. Ausrüstung: Matte. Worauf achten: Oberkörper aufrecht, Bewegung ruhig und im schmerzfreien Bereich, Knie am Boden ggf. mit Matte polstern.', 'Mobilisation', 'vordere_beinkette', null),
('Schultermobilisation mit dem Stab', 'Schultern', 'Ausführung: Einen Stab oder ein Handtuch mit beiden Händen breit greifen und mit gestreckten Armen über den Kopf nach hinten führen, so weit es die Beweglichkeit schmerzfrei zulässt, dann kontrolliert zurück nach vorn. Ausrüstung: Stab, Besenstiel oder Handtuch. Worauf achten: Griffbreite so wählen, dass die Bewegung schmerzfrei bleibt, langsames Tempo, Griffbreite bei Bedarf vergrößern statt die Schulter zu forcieren.', 'Mobilisation', 'sonstige', null),
('Handgelenk-Mobilisation', 'Handgelenke, Unterarme', 'Ausführung: Die Handgelenke abwechselnd langsam kreisen lassen sowie die Hände bei gestreckten Armen kontrolliert nach oben und unten abknicken. Ausrüstung: keine. Worauf achten: Bewegung langsam und im schmerzfreien Bereich, keine ruckartigen Bewegungen, bei Beschwerden die Amplitude reduzieren.', 'Mobilisation', 'sonstige', null),
('Knöchelmobilisation', 'Sprunggelenke', 'Ausführung: Im Sitzen oder Stehen die Füße abwechselnd langsam kreisen lassen sowie die Zehenspitzen abwechselnd Richtung Schienbein ziehen und wieder strecken. Ausrüstung: keine. Worauf achten: Bewegung kontrolliert durch den vollen, schmerzfreien Bewegungsradius führen, im Stehen ggf. an einer Wand festhalten.', 'Mobilisation', 'sonstige', null),
('Thorakale Rotation im Vierfüßlerstand', 'Brustwirbelsäule', 'Ausführung: Im Vierfüßlerstand mit stabilem Becken eine Hand hinter den Kopf legen und den Ellbogen kontrolliert Richtung Decke rotieren, Blick folgt dem Ellbogen, dann zurück und Seite wechseln. Ausrüstung: Matte. Worauf achten: Hüfte bleibt ruhig, Bewegung kommt ausschließlich aus der Brustwirbelsäule, langsames Tempo ohne Schwung.', 'Mobilisation', 'sonstige', null),
('Beinschwünge seitlich', 'Hüfte, Beine, Adduktoren', 'Ausführung: Mit sicherem Festhalten an einer Wand oder Stange ein Bein locker und kontrolliert seitlich vor dem Körper hin- und herschwingen lassen, Seite wechseln. Ausrüstung: Wand oder Stange zum Festhalten. Worauf achten: Oberkörper stabil, Bewegung aus der Hüfte statt aus dem Rumpf, Amplitude langsam steigern statt von Beginn an maximal auszuschwingen.', 'Mobilisation', 'sonstige', null),
('Frosch-Dehnung', 'Adduktoren, Hüfte', 'Ausführung: Im Vierfüßlerstand die Knie breit auseinander positionieren und das Becken langsam nach hinten Richtung Fersen schieben, bis eine deutliche Dehnung in der Leiste spürbar ist, Position ca. 20-30 Sekunden halten. Ausrüstung: Matte. Worauf achten: Dehnung langsam aufbauen, im schmerzfreien Bereich bleiben, gleichmäßige Atmung, Knie bei Bedarf mit Matte polstern.', 'Mobilisation', 'sonstige', null),
('Kobra-Dehnung', 'Bauch, unterer Rücken', 'Ausführung: In Bauchlage die Hände unter den Schultern aufsetzen und den Oberkörper langsam bis zur angenehmen Dehnung nach oben drücken, Becken bleibt am Boden, Position ca. 20-30 Sekunden halten. Ausrüstung: Matte. Worauf achten: Bewegung langsam aufbauen, kein Schmerz im unteren Rücken, Schultern entspannt und von den Ohren weg.', 'Mobilisation', 'rumpf_hinten', null),
('Vorbeuge im Stehen', 'Hintere Oberschenkelmuskulatur, Rücken', 'Ausführung: Im Stand mit leicht gebeugten Knien den Oberkörper langsam und locker nach vorn hängen lassen, Arme und Kopf hängen entspannt, Position ca. 20-30 Sekunden halten. Ausrüstung: keine. Worauf achten: Dehnung passiv wirken lassen statt zu federn, Knie bei Bedarf stärker beugen, langsam wieder aufrichten, um Schwindel zu vermeiden.', 'Mobilisation', 'hintere_beinkette', null),
('Große Armkreise', 'Schultern', 'Ausführung: Im aufrechten Stand beide Arme mit maximaler, schmerzfreier Reichweite große Kreise nach vorn und anschließend nach hinten ziehen lassen. Ausrüstung: keine. Worauf achten: Bewegung groß und kontrolliert statt hektisch, Rumpf bleibt stabil, ausreichend Platz um sich herum einplanen.', 'Mobilisation', 'sonstige', null),
('Faszienrolle Rücken', 'Rücken', 'Ausführung: Mit der Faszienrolle unter dem oberen Rücken liegend und Händen hinter dem Kopf verschränkt langsam vor- und zurückrollen, an Verspannungspunkten kurz verweilen. Ausrüstung: Faszienrolle. Worauf achten: Nacken entspannt, Bauch leicht angespannt, Bewegung langsam, unteren Rücken (Lendenwirbelsäule) konsequent aussparen.', 'Mobilisation', 'sonstige', null),
('Faszienrolle Oberschenkel', 'Oberschenkel, IT-Band', 'Ausführung: Mit der Faszienrolle unter dem Oberschenkel liegend bzw. auf den Armen abgestützt langsam vor- und zurückrollen, an Verspannungspunkten kurz verweilen. Ausrüstung: Faszienrolle. Worauf achten: Bewegung langsam, Rumpf stabil, Druck über die Armstützung dosieren, Kniegelenk selbst nicht direkt beplanken.', 'Mobilisation', 'sonstige', null),
('Assault Bike (Air Bike)', 'Ganzkörper & Herz-Kreislauf-System', 'Ausführung: Auf dem Air Bike mit aufrechter Haltung gleichzeitig in die Pedale treten und die Arme aktiv mitbewegen, Intensität schrittweise über das Tempo steuern. Ausrüstung: Assault Bike/Air Bike. Worauf achten: Aufrechte Haltung, gleichmäßiger Rhythmus zwischen Armen und Beinen, Intensität über Herzfrequenz oder Tempo steuern, ausreichend Aufwärmen vor hoher Intensität.', 'Cardio', 'sonstige', null),
('Seilspringen (Jump Rope)', 'Waden, Ganzkörper & Herz-Kreislauf-System', 'Ausführung: Mit dem Springseil in gleichmäßigem Rhythmus über die Fußballen mit nur geringer Sprunghöhe springen, die Handgelenke drehen das Seil. Ausrüstung: Springseil, ggf. dämpfender Untergrund. Worauf achten: Weiche, geräuscharme Landung über die Fußballen, Ellbogen nah am Körper, aufrechte Haltung, Knie leicht gebeugt zur Stoßdämpfung.', 'Cardio', 'sonstige', null),
('Schlittenschieben (Sled Push)', 'Beine, Gesäß & Herz-Kreislauf-System', 'Ausführung: Den beladenen Schlitten mit gestreckten oder leicht gebeugten Armen vor dem Körper über eine festgelegte Strecke schieben, Oberkörper dabei leicht nach vorn geneigt. Ausrüstung: Sled/Schlitten mit Gewicht. Worauf achten: Rücken gerade, Antrieb aus den Beinen statt aus dem Rücken, kurze kraftvolle Schritte, moderates Gewicht bei ungewohnter Belastung wählen.', 'Cardio', 'sonstige', null),
('Schlittenziehen (Sled Pull)', 'Rücken, Beine & Herz-Kreislauf-System', 'Ausführung: Den beladenen Schlitten über ein Seil oder einen Gurt mit gleichmäßigen Schritten rückwärts oder vorwärts ziehend über eine festgelegte Strecke bewegen. Ausrüstung: Sled/Schlitten mit Gewicht, Seil oder Zuggurt. Worauf achten: Rücken gerade, gleichmäßiges Tempo, Rumpf stabil, beim Rückwärtsgehen auf freie Strecke achten.', 'Cardio', 'sonstige', null),
('Tabata-Intervalle (20/10, freie Übungsauswahl)', 'Ganzkörper & Herz-Kreislauf-System', 'Ausführung: Kurze Hochintensitätsphase bei einer frei wählbaren Übung (z. B. Burpees, Mountain Climbers), gefolgt von einer kurzen Erholungsphase, über mehrere Runden im festen Wechsel wiederholen. Ausrüstung: je nach gewählter Übung. Worauf achten: Technik auch bei hoher Intensität sauber halten statt sie für Tempo zu opfern, Belastung an die eigene Fitness anpassen, ausreichend Aufwärmen vor der ersten Runde.', 'Cardio', 'sonstige', null),
('Boxen am Sandsack', 'Ganzkörper, Arme, Schultern', 'Ausführung: Im lockeren, hüftbreiten Stand Schlagkombinationen (Jab, Cross, Haken) mit Armen und Rumpfrotation kontrolliert gegen den Sandsack ausführen. Ausrüstung: Sandsack, Boxhandschuhe/Bandagen. Worauf achten: Handgelenke stabil halten und beim Treffer nicht abknicken, Rotation aus der Hüfte, lockere Beinarbeit, Bandagen/Handschuhe zum Schutz der Handgelenke verwenden.', 'Cardio', 'sonstige', null),
('Skaters (seitliche Sprünge)', 'Beine, Gesäß, Gleichgewicht', 'Ausführung: Seitliche, kontrollierte Sprünge von einem Bein auf das andere, das hintere Bein schwingt dabei hinter dem Standbein her, im Rhythmus die Seite wechseln. Ausrüstung: keine, rutschfester Untergrund. Worauf achten: Weiche Landung über den Fußballen, Knie leicht gebeugt und in Fußrichtung, Rumpf stabil.', 'Cardio', 'sonstige', null),
('Squat Jumps (Kniebeugensprünge)', 'Beine, Gesäß', 'Ausführung: Aus der Kniebeuge-Position mit hüftbreitem Stand explosiv nach oben abspringen, weich über die Fußballen mit gebeugten Knien landen und kontrolliert in die nächste Kniebeuge übergehen. Ausrüstung: keine. Worauf achten: Weiche Landung mit gebeugten Knien, Knie fallen dabei nicht nach innen, Rumpf stabil, Rhythmus an die eigene Fitness anpassen.', 'Cardio', 'sonstige', null),
('Tuck Jumps (Strecksprünge mit Knieanzug)', 'Beine, Gesäß', 'Ausführung: Aus dem hüftbreiten Stand explosiv nach oben springen und dabei beide Knie zur Brust anziehen, weich über die Fußballen mit gebeugten Knien landen. Ausrüstung: keine. Worauf achten: Weiche Landung, Rumpf stabil, ausreichend Platz nach oben und zur Seite einplanen, Sprunghöhe an die eigene Landekontrolle anpassen.', 'Cardio', 'sonstige', null),
('Schattenboxen (Shadow Boxing)', 'Ganzkörper, Arme', 'Ausführung: Freie Schlagkombinationen mit aktiver Beinarbeit und Rumpfrotation ohne Gerät oder Partner ausführen, kontinuierlich in Bewegung bleiben. Ausrüstung: keine. Worauf achten: Lockere, kontrollierte Bewegungen ohne die Arme komplett durchzustrecken, gleichmäßiger Rhythmus, aufrechte Grundhaltung.', 'Cardio', 'sonstige', null),
('Treppenlaufen (reale Treppe)', 'Beine, Gesäß & Herz-Kreislauf-System', 'Ausführung: Zügiges, kontrolliertes Treppauf- und -absteigen über mehrere Stockwerke oder eine Treppenstrecke, Tempo an die eigene Fitness anpassen. Ausrüstung: Treppe, festes Schuhwerk. Worauf achten: Fuß vollständig auf der Stufe aufsetzen, Geländer nur zur Sicherheit nutzen, beim Abstieg besonders auf sicheren Tritt achten, da hier das Sturzrisiko höher ist.', 'Cardio', 'sonstige', null),
('Walking-Intervalle im Freien', 'Beine & Herz-Kreislauf-System', 'Ausführung: Zügiges Gehen im Freien mit selbst gewählten, wechselnden Tempo-Phasen, aktiver Armeinsatz. Ausrüstung: keine, festes Schuhwerk. Worauf achten: Aufrechte Haltung, gleichmäßiger Atemrhythmus, Untergrund und Wetter berücksichtigen, Tempo bei unebenem Boden reduzieren.', 'Cardio', 'sonstige', null),
('Schwimmen (Bahnenziehen)', 'Ganzkörper & Herz-Kreislauf-System (gelenkschonend)', 'Ausführung: Kontinuierliches Bahnenziehen in einem Schwimmstil der Wahl (z. B. Kraul, Brust) mit sauberer Wasserlage, Tempo und Distanz an die eigene Fitness anpassen. Ausrüstung: Schwimmbad. Worauf achten: Gleichmäßige Atmung, saubere Technik vor Tempo, ausreichend Aufwärmen mit lockeren Bahnen zu Beginn.', 'Cardio', 'sonstige', null),
('Tanz-Cardio (freies Rhythmustraining)', 'Ganzkörper, Koordination & Herz-Kreislauf-System', 'Ausführung: Freies, rhythmisches Bewegen zu Musik mit kontinuierlichem, fließendem Einsatz von Armen und Beinen, Intensität über Tempo und Bewegungsumfang steuern. Ausrüstung: keine, ggf. Musik. Worauf achten: Gelenkschonende, fließende Bewegungen ohne abrupte Richtungswechsel, ausreichend Platz und rutschfesten Boden einplanen.', 'Cardio', 'sonstige', null),
('Indoor Cycling / Spinning (hohe Intensität)', 'Beine & Herz-Kreislauf-System', 'Ausführung: Auf dem Spinning-Rad mit korrekt eingestellter Sitzposition im Sitzen oder Wiegetritt mit wechselnder Intensität und Widerstand fahren. Ausrüstung: Spinning-/Indoor-Cycling-Rad. Worauf achten: Sattel- und Lenkerhöhe vor dem Start korrekt einstellen, gleichmäßige Trittfrequenz, Widerstand schrittweise statt sprunghaft steigern.', 'Cardio', 'sonstige', null),
('Medizinball-Slams', 'Ganzkörper, Rumpf, Schultern', 'Ausführung: Den Medizinball mit gestreckten Armen über den Kopf heben und mit kontrollierter Kraft aus der Hüfte auf den Boden schleudern, dann kontrolliert aufheben und wiederholen. Ausrüstung: Medizinball (wallfest). Worauf achten: Rumpf angespannt, Bewegung aus der Hüfte und den Schultern, Knie beim Aufheben leicht beugen statt mit rundem Rücken zu bücken.', 'Cardio', 'sonstige', null),
('Rudergerät (Dauerbelastung)', 'Ganzkörper & Herz-Kreislauf-System', 'Ausführung: Am Rudergerät mit fest angeschnalltem Fuß im gleichmäßigen Tempo über eine längere Distanz rudern, Beine-Rücken-Arme-Sequenz konstant halten. Ausrüstung: Rudergerät. Worauf achten: Bewegungsreihenfolge Beine-Rücken-Arme einhalten, aufrechter Oberkörper, gleichmäßiges Tempo statt Sprints, Rücken beim Zug nicht runden.', 'Cardio', 'sonstige', null),
('High Knees (schnelles Kniehebellauf auf der Stelle)', 'Beine, Hüftbeuger & Herz-Kreislauf-System', 'Ausführung: Auf der Stelle mit hoher Frequenz die Knie abwechselnd bis über Hüfthöhe anheben, aktiver, gegenläufiger Armeinsatz. Ausrüstung: keine, rutschfester Untergrund. Worauf achten: Aufrechte Haltung, Landung weich über den Fußballen, hohe Frequenz statt große Schritte, Rumpf stabil halten.', 'Cardio', 'sonstige', null),
('Plank Jacks (Unterarmstütz mit Beinsprung)', 'Rumpf, Beine & Herz-Kreislauf-System', 'Ausführung: Im Unterarmstütz mit angespanntem Rumpf die Beine mit einem kleinen, kontrollierten Sprung auseinander und wieder zusammenführen. Ausrüstung: Matte. Worauf achten: Becken bleibt ruhig und auf einer Höhe, kein Durchhängen oder Aufstellen der Hüfte, kontrollierte Landung, Tempo an die eigene Fitness anpassen.', 'Cardio', 'sonstige', null),
('Laufband-Sprintintervalle (Tempowechsel)', 'Beine & Herz-Kreislauf-System', 'Ausführung: Auf dem Laufband im Wechsel kurze Sprintphasen mit hoher Geschwindigkeit und längere Erholungsphasen im Gehen oder lockeren Laufen kombinieren, Geschwindigkeit dabei stets kontrolliert anpassen. Ausrüstung: Laufband. Worauf achten: Geschwindigkeit schrittweise steigern statt abrupt hochzuschalten, sichere Handhabung der Konsole während des Tempowechsels, ausreichend Aufwärmen vor dem ersten Sprint, Seitenholme im Notfall nutzen.', 'Cardio', 'sonstige', null);
